import React from 'react';

const testimonials = [
  { name: 'DJ Malik', time: "Il y'a deux heures", text: "Grâce à Djamano, j'ai trouvé de nouveaux clients sans bouger de mon studio.", avatar: 'M', featured: false },
  { name: 'Clarisse Kaboré', time: "Il y'a 2 semaines", text: "J'adore pouvoir découvrir des événements près de moi et acheter mes billets directement en ligne.", avatar: 'C', featured: true },
  { name: 'Shailesh Kushwaha', time: "Il y'a un mois", text: "Avant Djamano, gérer la billetterie et les réservations était un vrai casse-tête. Aujourd'hui, tout est centralisé.", avatar: 'S', featured: false },
];

const TestimonialsSection = () => {
  const s = {
    section: { background: '#F7F7F7', padding: '90px 32px', fontFamily: 'Poppins, sans-serif' },
    wrapper: { maxWidth: 1200, margin: '0 auto' },
    eyebrow: { display: 'inline-flex', alignItems: 'center', gap: 8, background: '#FFF3ED', color: '#FF5A00', padding: '6px 14px', borderRadius: 30, fontSize: 12, fontWeight: 600, marginBottom: 20 },
    title: { fontSize: 34, fontWeight: 800, color: '#111', fontFamily: 'Poppins, sans-serif', letterSpacing: '-0.6px', marginBottom: 48 },
    orange: { color: '#FF5A00' },
    grid: { display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: 22 },
    card: (f) => ({ borderRadius: 20, padding: '28px 24px', display: 'flex', flexDirection: 'column', gap: 14, background: f ? '#FF5A00' : '#fff', border: f ? 'none' : '1.5px solid #ebebeb' }),
    cardTop: { display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' },
    avatar: (f) => ({ width: 46, height: 46, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 18, fontWeight: 700, fontFamily: 'Poppins, sans-serif', background: f ? 'rgba(255,255,255,.25)' : '#FFF3ED', color: f ? '#fff' : '#FF5A00' }),
    time: (f) => ({ fontSize: 11, fontFamily: 'Poppins, sans-serif', fontWeight: 400, color: f ? 'rgba(255,255,255,.7)' : '#bbb' }),
    name: (f) => ({ fontSize: 15, fontWeight: 700, fontFamily: 'Poppins, sans-serif', color: f ? '#fff' : '#111' }),
    text: (f) => ({ fontSize: 13.5, lineHeight: 1.72, fontFamily: 'Poppins, sans-serif', fontWeight: 400, color: f ? 'rgba(255,255,255,.88)' : '#666' }),
    stars: { display: 'flex', gap: 3 },
    star: (f) => ({ fontSize: 13, color: f ? 'rgba(255,255,255,.9)' : '#FF5A00' }),
  };

  return (
    <section style={s.section}>
      <div style={s.wrapper}>
        <div style={s.eyebrow}>Témoignages</div>
        <h2 style={s.title}>Témoignages d'<span style={s.orange}>Utilisateurs </span></h2>
        <div style={s.grid}>
          {testimonials.map((t) => (
            <div key={t.name} style={s.card(t.featured)}>
              <div style={s.cardTop}>
                <div style={s.avatar(t.featured)}>{t.avatar}</div>
                <span style={s.time(t.featured)}>{t.time}</span>
              </div>
              <div style={s.name(t.featured)}>{t.name}</div>
              <div style={s.text(t.featured)}>{t.text}</div>
              <div style={s.stars}>
                {[...Array(5)].map((_, i) => <span key={i} style={s.star(t.featured)}>★</span>)}
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default TestimonialsSection;
